<?php
namespace App\Security\Voter;
use App\Entity\Groupe;use App\Entity\GroupeMember;use App\Entity\User;use App\Repository\GroupeMemberRepository;use Symfony\Component\Security\Core\Authentication\Token\TokenInterface;use Symfony\Component\Security\Core\Authorization\Voter\Voter;
final class GroupeVoter extends Voter { public const VIEW='FACTION_VIEW';public const EDIT='FACTION_EDIT';public const ARCHIVE='FACTION_ARCHIVE';public const MANAGE_MEMBERS='FACTION_MANAGE_MEMBERS'; public function __construct(private readonly GroupeMemberRepository $members){} protected function supports(string $attribute,mixed $subject):bool{return in_array($attribute,[self::VIEW,self::EDIT,self::ARCHIVE,self::MANAGE_MEMBERS],true)&&$subject instanceof Groupe;} protected function voteOnAttribute(string $attribute,mixed $g,TokenInterface $token,?\Symfony\Component\Security\Core\Authorization\Voter\Vote $vote=null):bool{$u=$token->getUser();if(!$u instanceof User)return $attribute===self::VIEW&&$g->getVisibility()===Groupe::VISIBILITY_PUBLIC;if($u->getRole()==='ADMIN')return true;$m=$this->members->findActive($g,$u);if($attribute===self::VIEW)return $g->getVisibility()===Groupe::VISIBILITY_PUBLIC||$m!==null;if(!$m)return false;return match($attribute){self::EDIT,self::ARCHIVE=>$m->getRole()===GroupeMember::OWNER,self::MANAGE_MEMBERS=>in_array($m->getRole(),[GroupeMember::OWNER,GroupeMember::OFFICER],true),default=>false};}}
